TABLE_PATTERNS = [
    (r" & No & ", r" & --- & "),
    (r" & No \\", r" & --- \\"),
    (r" & No (exact scaling) & ", r" & --- (exact scaling) & "),
]


def main() -> None:
    text = TEX.read_text(encoding="utf-8")
    for old, new in TABLE_PATTERNS:
        text = text.replace(old, new)
    normalized = [
        (old.replace("\\n", "\n"), new.replace("\\n", "\n"))
        for old, new in PAIRS
    ]
    missing = [(old, new) for old, new in normalized if text.count(old) != 1]
    if missing:
        for old, _ in missing:
            print(f"MISSING/AMBIGUOUS ({text.count(old)}): {old[:90]}")
        raise SystemExit(1)
    for old, new in normalized:
        text = text.replace(old, new)
    TEX.write_text(text, encoding="utf-8")
    print(f"Applied {len(normalized)} affirmative rewrites.")


if __name__ == "__main__":
    main()
